import type { OpenAiIncompleteDetails } from './open-ai-incomplete-details';
import type { OpenAiResponseError } from './open-ai-response-error';
import type { OpenAiResponseOutputItem } from './open-ai-response-output-item';
import type { OpenAiResponseUsage } from './open-ai-response-usage';
import type { ProviderJsonValue } from './provider-json-value';

/** OpenAI-compatible open ai response schema exposed by Claw Router. */
export interface OpenAiResponse {
  /** Unix timestamp in seconds when the response was created. */
  created_at?: string;
  /** Error field on the open ai response, using the open ai response error module. */
  error?: OpenAiResponseError;
  /** Response identifier. */
  id: string;
  /** Incomplete details field on the open ai response, using the open ai incomplete details module. */
  incomplete_details?: OpenAiIncompleteDetails;
  /** Model id used by the upstream response. */
  model: string;
  /** Object type, normally response. */
  object: 'response';
  /** Output items generated by the response. */
  output: OpenAiResponseOutputItem[];
  /** Convenience text output when returned by the upstream. */
  output_text?: string;
  /** Response status. */
  status?: 'queued' | 'in_progress' | 'completed' | 'failed' | 'cancelled' | 'incomplete';
  /** Usage field on the open ai response, using the open ai response usage module. */
  usage?: OpenAiResponseUsage;
}
